create function retirer_stock() returns trigger
language plpgsql
as $$
begin
  update produits set stock = stock - new.quantite where id = new.produit_id;
  return new;
end;
$$;

create trigger apres_commande
after insert on commandes
for each row execute function retirer_stock();

